//
//! The build half of SQLite's runtime-loading route: three modules and one
//! generated file.
//!
//! An SDK that ships the runtime route calls `createModule` in place of
//! `translate.createModule()` and imports what comes back as its `c` module.
//! Nothing here links the native library. That is the point: in this
//! configuration the symbols arrive through the platform loader at run time,
//! and linking the archive as well would make the linker demand them before
//! `load` ever runs.
//!
//!   rt        runtime/loader.zig, the reusable core. Pure Zig; imported by the
//!             facade in both configurations, because `LoadSource` and
//!             `LoadError` are this SDK's public types and must be the same
//!             types whichever configuration is built.
//!   library   runtime/library.zig, this SDK's descriptor: the namespaced
//!             synchronization binding and the one load-time check.
//!   dispatch  generated by runtime/generate.zig from the real translation
//!             output: the table, the wrappers, `load`, and the re-exported
//!             translated namespace. It imports `rt`, `library` and the
//!             generator's patched translation as `c_native`, which imports the
//!             dispatch back as `c_routed`.
//!   sync.c    compiled into the dispatch with `-DRT_SYNC_PREFIX=sqlite_rt`, so
//!             its symbols cannot collide with another SDK's.
//!
//! ## The one thing a caller must not do
//!
//! Do not link the compiled C archive into a module that imports this dispatch.
//! The facade's `c` import is the dispatch, and nothing else in the graph should
//! reference the library, or the linker resolves the symbols statically and the
//! runtime route silently becomes a linked one.
//!
//! ## What is routed, and what is not
//!
//! The translated header for this SDK is `zig/translate.h`, which includes
//! exactly `<sqlite3.h>` and defines no macro. `src/sqlite3.h` declares 366
//! names: 365 functions and one data object, `sqlite3_version`
//! (`src/sqlite3.h:188`). Every one of those 366 is routed: a provider that does
//! not export the whole header-declared API is refused rather than half used.
//! `provider_optional` and `provider_excluded` below are therefore empty, and
//! are written out rather than omitted so that adding a header with an optional
//! or deliberately-direct entry point is a change in this file with a name in
//! it.
//!
//! Those 366 are exactly what this build compiles. Every one of the 365 declared
//! functions is defined in the vendored amalgamation: reading `src/sqlite3.c`
//! for a definition line of the form `SQLITE_API ... sqlite3_<name>(` at column
//! zero finds all 365, and `src/sqlite3.c:187463` is the
//! `SQLITE_API const char sqlite3_version[] = SQLITE_VERSION;` the header's data
//! object needs. No declaration is conditional on a compile option this build
//! does not define, because this build defines no `SQLITE_*` option at all - see
//! `build.zig`, "No compile options are defined".
//!
//! ## Why the noise list below is empty, and what would break it
//!
//! `zig translate-c` emits a declaration for every function it parses in the
//! include closure of the header it is given, whether or not this build calls
//! it. Those are the C library's symbols, not the provider's: a `libsqlite3.so`
//! exports `sqlite3_*` and nothing else, so routing a `printf` or a `malloc`
//! would fail the load outright or, worse, resolve it out of the C library the
//! provider itself depends on.
//!
//! For this SDK the list is empty for a source-confirmed reason rather than an
//! empirical one. `src/sqlite3.h` opens exactly one system header in the whole
//! 14 349-line file:
//!
//! ```c
//! 35:#include <stdarg.h>     /* Needed for the definition of va_list */
//! ```
//!
//! and `grep -n '^#include' src/sqlite3.h` prints that line and nothing else.
//! `<stdarg.h>` declares no function: in every C library in this toolchain's
//! distribution it is `va_list`, `va_start`, `va_arg`, `va_end`, `va_copy` and
//! the compiler's own builtin list, all of which are macros or compiler
//! intrinsics. The header reaches it for three declarations and nothing else -
//! `sqlite3_vmprintf` (`src/sqlite3.h:3239`), `sqlite3_vsnprintf`
//! (`src/sqlite3.h:3241`) and `sqlite3_str_vappendf` (`src/sqlite3.h:8880`) -
//! each of which has a `va_list` parameter. A `va_list` is a type, not a symbol.
//! So the translation of `zig/translate.h` carries SQLite's 366 names and no
//! foreign function declarations, and there is nothing to classify as noise.
//!
//! That is a claim about the headers, and it is checked rather than assumed:
//! `tools/check-provenance.sh` re-reads `src/sqlite3.h` and fails if any
//! `#include` but `<stdarg.h>` appears. If a future release adds a header to the
//! closure, that check fires, the list below has to be filled in from the new
//! translation, and until it is, the loader's answer to a foreign name is a
//! `MissingSymbol` naming that symbol - which is a diagnosable failure and not a
//! silent mis-dispatch.
//!
//! ## `sqlite3ext.h` is installed and not translated
//!
//! `upstream/main.mk:1613-1614` installs two headers, `sqlite3.h` and
//! `src/sqlite3ext.h`, and `build.zig` installs the same two. `sqlite3ext.h` is
//! deliberately not in the translation, for a reason in the file itself: its
//! entire interface is `#define`s that redirect each call through the global
//! `sqlite3_api` structure (`src/sqlite3ext.h:402-736`), and the one symbol those
//! macros need - `extern const sqlite3_api_routines *sqlite3_api` - exists only
//! in a file compiled as a loadable extension
//! (`SQLITE_EXTENSION_INIT3`, `src/sqlite3ext.h:731-734`). A `libsqlite3.so` does
//! not define it, so translating that header would add a name no conforming
//! provider exports, and every load would end in `MissingSymbol`.

const std = @import("std");

/// The prefix `runtime/sync.c` is compiled with.
///
/// `runtime/library.zig` declares the same prefix in the symbol names it binds.
/// The two must agree, and a build where they do not fails to link, which is
/// the whole error report: there is no runtime path that could hide it.
///
/// A build that needs a second, independent instance of this SDK in one binary
/// should change this value *and* the prefix in `runtime/library.zig`, and then
/// give the second instance its own copy of both files. Nothing else in the
/// package assumes one instance.
const sync_prefix = "sqlite_rt";

/// `extern` declarations that are the C library's, not SQLite's.
///
/// Empty, and the module comment above says why with the header line that makes
/// it empty: `src/sqlite3.h:35` is the only `#include` in the file and
/// `<stdarg.h>` declares no function. Written out rather than omitted so that
/// adding a system header to the closure is a change in this file with a name
/// in it.
///
/// The list is comma-separated with a trailing comma on every line, because
/// `runtime/generate.zig` splits it on `,` and a Zig multiline string
/// concatenates its lines with nothing between them: a line that does not end
/// in a delimiter glues its last name to the first name of the next line, and
/// neither real name is matched. It is empty, so there is no such line today.
const libc_noise = "";

/// `extern` declarations the provider may legitimately not have.
///
/// None. Every function `sqlite3.h` declares is defined in the amalgamation
/// this package compiles, and a provider that does not export one of them is
/// refused rather than half used. The list is spelled out so that adding a
/// header with an optional entry point is a build-file change with a name in
/// it.
const provider_optional = "";

/// `extern` declarations this build does not require a provider to export.
///
/// None, for the reason the optional list gives: there is no header-declared
/// SQLite entry point that a conforming provider is allowed to omit. The one
/// candidate, `sqlite3_api`, is not in this translation at all - see the module
/// comment on `sqlite3ext.h`.
///
/// A name here is routed and optional rather than direct; only `libc_noise`
/// above stays direct.
const provider_excluded = "";

/// The loader core, for a *linked* build to import.
///
/// A linked build has no dispatch, so the facade needs the core module itself
/// for the two public types `LoadSource` and `LoadError`: they are this SDK's
/// types and they must be the same types a caller names in either
/// configuration. It costs a linked build two declarations and no code, since
/// nothing else in that module is referenced until a configuration actually
/// instantiates the loader.
///
/// A runtime-loading build must *not* import this separately: `createModule`
/// makes the one core instance the dispatch uses, and the dispatch re-exports
/// the two types from it. Two instances would be two sets of types, and a
/// consumer would be naming one while `load` expects the other.
pub fn createCoreModule(
    b: *std.Build,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    return b.createModule(.{
        .root_source_file = b.path("runtime/loader.zig"),
        .target = target,
        .optimize = optimize,
        // The Unix backend calls `dlopen`, which is libc. Nothing in this module
        // is compiled into a linked build, so this costs nothing there.
        .link_libc = true,
    });
}

/// The runtime-loaded `c` module for one target.
///
/// `translate` is the translation step for that same target and configuration;
/// its output is read by the generator, so the dispatch describes the headers
/// this build actually selected rather than another one.
pub fn createModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    const core = createCoreModule(b, target, optimize);

    const library = b.createModule(.{
        .root_source_file = b.path("runtime/library.zig"),
        .target = target,
        .optimize = optimize,
    });
    library.addImport("rt", core);

    return createDispatchModule(b, translate, target, optimize, core, library);
}

const GeneratedSources = struct {
    native: std.Build.LazyPath,
    dispatch: std.Build.LazyPath,
};

fn createDispatchModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
    core: *std.Build.Module,
    library: *std.Build.Module,
) *std.Build.Module {
    const sources = generateDispatch(b, translate, target);

    const dispatch = b.createModule(.{
        .root_source_file = sources.dispatch,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    dispatch.addImport("rt", core);
    dispatch.addImport("library", library);
    // The translated headers, under a name that says what it is. Every type and
    // constant in the dispatch is re-exported from here rather than restated, so
    // `c.sqlite3` in a facade and `c_native.sqlite3` in the dispatch are one
    // type.
    //
    // The root is the generator's *patched* translation, not the raw one the
    // translate step wrote. `const __root = @import("c_routed");` is what makes
    // a macro-expanded struct member that names a library function resolve to
    // the routed wrapper rather than escaping to a native `extern` this route
    // never links. That repointing is why the two modules import each other.
    const native = b.createModule(.{
        .root_source_file = sources.native,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    native.addImport("c_routed", dispatch);
    dispatch.addImport("c_native", native);
    dispatch.addCSourceFiles(.{
        .files = &.{"runtime/sync.c"},
        .flags = &.{b.fmt("-DRT_SYNC_PREFIX={s}", .{sync_prefix})},
        .language = .c,
    });
    return dispatch;
}

/// Runs the generator over the translation step's real output.
///
/// The generator is a host program built and run by this build, so the dispatch
/// is produced for the target being built from that target's own translation.
/// Nothing is cached across configurations: a different header configuration
/// produces a different translation step output, which produces a different
/// dispatch.
fn generateDispatch(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
) GeneratedSources {
    const generator = b.addExecutable(.{
        .name = b.fmt("sqlite-runtime-generate-{s}", .{
            target.result.zigTriple(b.allocator) catch @panic("unspellable target"),
        }),
        .root_module = b.createModule(.{
            .root_source_file = b.path("runtime/generate.zig"),
            .target = b.graph.host,
            .optimize = .Debug,
        }),
    });

    const run = b.addRunArtifact(generator);
    run.addArg("--library");
    run.addArg("sqlite");
    run.addArg("--translate");
    run.addFileArg(translate.getOutput());
    if (libc_noise.len != 0) {
        run.addArg("--noise");
        run.addArg(libc_noise);
    }
    if (provider_optional.len != 0) {
        run.addArg("--optional");
        run.addArg(provider_optional);
    }
    if (provider_excluded.len != 0) {
        run.addArg("--exclude");
        run.addArg(provider_excluded);
    }
    run.addArg("--native-output");
    const native_source = run.addOutputFileArg("native.zig");
    run.addArg("--output");
    const dispatch_source = run.addOutputFileArg("dispatch.zig");
    return .{ .native = native_source, .dispatch = dispatch_source };
}
